1	#include "capture/pir/pir_logic.h"
2	
3	#include <string.h>
4	
5	void pir_filter_init(struct pir_filter *f, int64_t start_ns, int64_t warmup_ns, int initial_level)
6	{
7		memset(f, 0, sizeof *f);
8		f->warmup_until_ns = start_ns + warmup_ns;
9		f->level = initial_level ? 1 : 0;
10	}
11	
12	enum pir_verdict pir_filter_edge(struct pir_filter *f, int rising, int64_t ts_ns)
13	{
14		int level = rising ? 1 : 0;
15	
16		if (level == f->level) {
17			f->suppressed++;
18			return PIR_DUPLICATE;
19		}
20		/* Track the level even during warm-up so the first real edge is correct. */
21		f->level = level;
22		if (ts_ns < f->warmup_until_ns) {
23			f->suppressed++;
24			return PIR_WARMUP;
25		}
26		f->forwarded++;
27		return PIR_FORWARD;
28	}
